      world.set(itemId, Beatitude, { state: "uncursed" });
      world.emit?.("fountain:dip", { actor, targetId, itemId, effect: "uncurse", itemName });
    } else {
      world.emit?.("fountain:dip", { actor, targetId, itemId, effect: "nothing", itemName });
    }
